def backfill_unambiguous_stamps(apps, schema_editor):
    """Only infer provenance where recorded completion boundaries are unambiguous.

    Old reversals never recorded their stamp lot. Reconstructing those by guessing
    could reverse an already redeemed benefit, so leave such histories for support.
    Current commands detect missing provenance and fail without changing balances.
    """
    database = schema_editor.connection.alias
    Card = apps.get_model('loyalty', 'Card')
    Purchase = apps.get_model('loyalty', 'Purchase')
    Reward = apps.get_model('loyalty', 'Reward')
    Reversal = apps.get_model('loyalty', 'PurchaseReversal')
    Contribution = apps.get_model('loyalty', 'StampContribution')
    for card in Card.objects.using(database).iterator():
        purchases = list(Purchase.objects.using(database).filter(
            business_id=card.business_id, customer_id=card.customer_id,
        ).order_by('created_at', 'id'))
        if not purchases:
            continue
        ids = [p.id for p in purchases]
        if Reversal.objects.using(database).filter(purchase_id__in=ids).exists():
            continue
        rewards = list(Reward.objects.using(database).filter(
            business_id=card.business_id, customer_id=card.customer_id,
        ))
        if any(r.status not in ('available', 'redeemed') or r.purchase_id not in ids for r in rewards):
            continue
        by_completion = {r.purchase_id: r for r in rewards}
        pending, rows = [], []
        for purchase in purchases:
            pending.append(purchase.id)
            reward = by_completion.get(purchase.id)
            if reward:
                rows.extend(Contribution(purchase_id=pid, reward_id=reward.id) for pid in pending)
                pending = []
        if len(pending) != card.stamps:
            continue
        rows.extend(Contribution(purchase_id=pid) for pid in pending)
        Contribution.objects.using(database).bulk_create(rows)


